 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchKeywrd_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20010.searchKeywrd_onsubmit' }); }
};

